// iCare's logo (Cam): "Family hearts" in golden peach glass, a big heart and a small heart together.
// Same drawing as public/icons/icare-mark.svg and the app icons (generated by scripts/make-icons.mjs).
import { useId } from "react";

// Continuous-corner squircle (superellipse n = 5), like the iOS app icon mask, on a 100 x 100 canvas.
const SQUIRCLE = (() => {
  const pts: string[] = [];
  for (let i = 0; i < 360; i += 4) {
    const t = (i * Math.PI) / 180, c = Math.cos(t), s = Math.sin(t);
    pts.push(`${(50 + 50 * Math.sign(c) * Math.abs(c) ** 0.4).toFixed(2)} ${(50 + 50 * Math.sign(s) * Math.abs(s) ** 0.4).toFixed(2)}`);
  }
  return `M${pts.join("L")}Z`;
})();
const BIG = "M42 76.5C19 62.4 10.5 49.6 10.5 37.6 10.5 27.2 18.3 19.5 28.2 19.5c6 0 10.8 2.9 13.8 7.7 3-4.8 7.8-7.7 13.8-7.7 9.9 0 17.7 7.7 17.7 18.1 0 12-8.5 24.8-31.5 38.9Z";
const SMALL = "M67 83C54.3 75.4 49.6 68 49.6 61.2c0-5.8 4.2-10 9.7-10 3.4 0 6 1.6 7.7 4.3 1.7-2.7 4.3-4.3 7.7-4.3 5.5 0 9.7 4.2 9.7 10 0 6.8-4.7 14.2-17.4 21.8Z";

export default function BrandMark({ size = 32, className = "", title }: { size?: number; className?: string; title?: string }) {
  const id = useId().replace(/:/g, "");
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 100 100"
      className={className}
      role={title ? "img" : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : true}
      focusable="false"
    >
      <defs>
        <linearGradient id={`${id}bg`} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#FFD98A" />
          <stop offset=".5" stopColor="#FFA960" />
          <stop offset="1" stopColor="#FF7C4E" />
        </linearGradient>
        <radialGradient id={`${id}light`} cx=".22" cy=".12" r=".9">
          <stop offset="0" stopColor="#fff" stopOpacity=".38" />
          <stop offset=".55" stopColor="#fff" stopOpacity="0" />
        </radialGradient>
        <linearGradient id={`${id}big`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#FFFFFF" />
          <stop offset="1" stopColor="#FFF1E2" />
        </linearGradient>
        <linearGradient id={`${id}small`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#FF8A5C" />
          <stop offset="1" stopColor="#F2533F" />
        </linearGradient>
        <linearGradient id={`${id}rim`} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#fff" stopOpacity=".95" />
          <stop offset=".45" stopColor="#fff" stopOpacity=".15" />
          <stop offset="1" stopColor="#fff" stopOpacity="0" />
        </linearGradient>
        <clipPath id={`${id}sq`}>
          <path d={SQUIRCLE} />
        </clipPath>
        <clipPath id={`${id}bigc`}>
          <path d={BIG} />
        </clipPath>
        <clipPath id={`${id}smc`}>
          <path d={SMALL} />
        </clipPath>
        <filter id={`${id}sh`} x="-30%" y="-30%" width="160%" height="170%">
          <feDropShadow dx="0" dy="2.6" stdDeviation="3" floodColor="#8a3a14" floodOpacity=".22" />
        </filter>
      </defs>
      <g clipPath={`url(#${id}sq)`}>
        <rect width="100" height="100" fill={`url(#${id}bg)`} />
        <rect width="100" height="100" fill={`url(#${id}light)`} />
        <g transform="translate(3 0)">
          <path d={BIG} fill={`url(#${id}big)`} filter={`url(#${id}sh)`} />
          <path d={BIG} fill="none" stroke={`url(#${id}rim)`} strokeWidth="2.4" clipPath={`url(#${id}bigc)`} />
          <path d={SMALL} fill={`url(#${id}small)`} opacity=".9" filter={`url(#${id}sh)`} />
          <path d={SMALL} fill="none" stroke={`url(#${id}rim)`} strokeWidth="2" clipPath={`url(#${id}smc)`} />
        </g>
      </g>
    </svg>
  );
}
